CREATE VIEW gold.rpt_service_level_material_month AS SELECT v.calmonth, v.material, v.do_qty, v.po_qty, v.fill_rate, s.bill_qty sales_bill_qty, s.bill_val sales_bill_val, t.tot_stck, CASE WHEN v.fill_rate IS NULL THEN 'unknown' WHEN v.fill_rate < 0.5 THEN 'low_fill' WHEN v.fill_rate < 0.8 THEN 'medium_fill' ELSE 'high_fill' END fill_rate_band FROM gold.corr_service_material_month v LEFT OUTER JOIN gold.corr_sales_material_month s ON v.calmonth = s.calmonth AND v.material = s.material LEFT OUTER JOIN gold.corr_stock_material_month t ON v.calmonth = t.calmonth AND v.material = t.material
